INSERT INTO `clients` (`slug`, `name`, `kicker`, `type`, `role`, `period`, `location`, `website`, `logo`, `metric`, `metric_label`, `summary`, `challenge`, `what_i_did`, `outcome`, `stack`, `facts`, `store_url`, `published`, `sort_order`) VALUES
  ('evlab', 'EVLAB', 'Chalhoub Group · Mobility', 'Electric mobility platform', 'Mobile Engineering Lead', '07/2023 — 01/2026', 'Dubai, UAE', 'https://www.ev-lab.io', '/media/clients/evlab.png', 'End-to-end', 'mobile ownership', 'An electric mobility platform for rentals, leasing, and marketplace — with mobile delivery owned end to end, from architecture to production support.', 'EVLAB carries three business models at once — daily rentals, long-term leasing, and a marketplace — inside one product and one brand. The mobile apps had to serve all three without splitting into separate codebases, while meeting Chalhoub Group standards for security, release management, and production support.', '["Led mobile engineering for the EVLAB platform across iOS and Android.","Architected Flutter apps on Clean Architecture with Riverpod, SOLID boundaries, and reusable components.","Integrated secure REST APIs, authentication, cloud services, analytics, and third-party SDKs.","Coordinated Mobile, Backend, Product, UX/UI, QA, DevOps, and business teams through delivery.","Implemented Codemagic CI/CD, reducing manual release effort, and owned release management and production support."]', 'Mobile shipped as one platform instead of three parallel apps: shared architecture, shared components, and a release process the wider team could run. Ownership covered the full lifecycle — planning, development, testing, store releases, and production support — through the end of the engagement in January 2026.', '["Flutter","Dart","Clean Architecture","Riverpod","REST APIs","Codemagic","iOS","Android"]', '[["Engagement","Jul 2023 — Jan 2026"],["Role","Mobile Engineering Lead"],["Platforms","iOS · Android"],["Based in","Dubai, UAE"]]', 'https://apps.apple.com/app/id1635102548', 1, 0),
  ('good2go-loans', 'Good2Go Loans', 'Beedev Solutions · FinTech', 'Digital lending', 'Senior Flutter Developer', '08/2019 — 03/2021', 'Australia · remote', 'https://www.goodtogoloans.com.au', '/media/clients/good2go.png', '50K+', 'users in New Zealand', 'A digital lending app used by 50,000+ people across New Zealand — onboarding, authentication, account journeys, and store releases owned end to end.', 'Lending products earn trust in the first few minutes. Identity, eligibility, and account access have to be clear, fast, and correct on the phones people actually carry — and the app has to satisfy financial-product review on both stores, release after release.', '["Built onboarding, authentication, account journeys, notifications, and API integrations.","Designed a scalable Flutter codebase on Clean Architecture and SOLID principles.","Owned Android and iOS deployment, monitoring, and continuous improvement.","Worked directly with the lending team on product changes and release requirements."]', 'The product reached 50,000+ users across New Zealand, and the architecture became the base the team kept extending rather than rewriting. Releases stayed predictable on both platforms for the life of the engagement.', '["Flutter","Dart","Clean Architecture","SOLID","REST APIs","Push notifications","iOS","Android"]', '[["Engagement","Aug 2019 — Mar 2021"],["Role","Senior Flutter Developer"],["Reach","50,000+ users"],["Market","New Zealand"]]', 'https://apps.apple.com/app/id1542316639', 1, 1),
  ('nakheel-marinas', 'Nakheel Marinas', 'Belong Interactive · Hospitality', 'Marina & lifestyle', 'Lead Senior Software Engineer (Mobile)', '08/2022 — 06/2023', 'Dubai, UAE', 'https://www.nakheelmarinas.com', '/media/clients/nakheel.png', '15K+', 'first-month downloads', 'A marina and lifestyle app shipped with a Flutter team under a fixed release train — 15,000+ downloads in its first month.', 'Hospitality apps ship against deadlines that do not move: a season opens, a marina is announced, a campaign goes live. The build needed a team of Flutter engineers working to one architecture and one standard, with authentication, notifications, analytics, and third-party services integrated on schedule.', '["Led the Flutter team on architecture, standards, code review, and production delivery.","Ran sprint planning, task breakdown, estimation, and delivery coordination.","Integrated REST APIs, authentication, analytics, notifications, and third-party services.","Shipped the app on the fixed release train and supported it in production."]', 'The app launched to 15,000+ downloads in its first month and gave the Belong Interactive team a delivery pattern for the hospitality apps that followed.', '["Flutter","Dart","REST APIs","Authentication","Analytics","Push notifications","iOS","Android"]', '[["Engagement","Aug 2022 — Jun 2023"],["Role","Lead Senior Software Engineer (Mobile)"],["Launch","15,000+ first-month downloads"],["Based in","Dubai, UAE"]]', NULL, 1, 2)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `kicker` = VALUES(`kicker`), `type` = VALUES(`type`), `role` = VALUES(`role`), `period` = VALUES(`period`), `location` = VALUES(`location`), `website` = VALUES(`website`), `logo` = VALUES(`logo`), `metric` = VALUES(`metric`), `metric_label` = VALUES(`metric_label`), `summary` = VALUES(`summary`), `challenge` = VALUES(`challenge`), `what_i_did` = VALUES(`what_i_did`), `outcome` = VALUES(`outcome`), `stack` = VALUES(`stack`), `facts` = VALUES(`facts`), `store_url` = VALUES(`store_url`), `published` = VALUES(`published`), `sort_order` = VALUES(`sort_order`);


INSERT INTO `apps` (`slug`, `name`, `tagline`, `role`, `year`, `platforms`, `genre`, `icon`, `screenshots`, `rating_value`, `rating_count`, `stack`, `links`, `summary`, `features`, `story`, `metrics`, `published`, `sort_order`) VALUES
  ('duas-and-aamal', 'Duas and Aamal', 'A daily companion for duas, aamal, and prayer — built Gujarati-first.', 'Creator · Flutter developer', '2023 — present', '["iOS","Android"]', 'Education', '/media/apps/duas-and-aamal/icon.webp', '["/media/apps/duas-and-aamal/shot1.webp","/media/apps/duas-and-aamal/shot2.webp"]', 4.9, 1058, '["Flutter","Dart","Firebase","Offline-first","5 languages","Android TV"]', '{"ios":"https://apps.apple.com/ae/app/duas-and-aamal/id6478907381","android":"https://play.google.com/store/apps/details?id=app.duasandaamal.com"}', 'A complete Quran companion app: Quran with Gujarati translation, duas, aamal, ziyarats, Jafari prayer times with moon-sighting adjustment, tasbih, qibla, widgets, and offline content in five languages.', '["Quran with Gujarati translation and Arabic text","Duas, aamal, and ziyarats with offline access","Jafari prayer times with moon-sighting adjustment","Tasbih counter, Qibla direction, home-screen widgets","English, Urdu, Gujarati, Swahili, and Persian","Prayer notifications, bookmarks, and an Android TV layout"]', 'Most religious apps treat Gujarati as a translation afterthought. I built Duas and Aamal around the opposite assumption: Gujarati-speaking families should get a first-class experience, with Arabic text rendered correctly and prayer times calculated properly rather than approximated. The content pipeline runs through a small custom CMS (duas-crm), so updates ship without an app release. Five languages, offline access, and a 4.9-star rating on Google Play came from listening to the community that uses it daily.', '[["4.9★","Google Play rating"],["1,058","Play reviews"],["5","Languages"],["Offline","Full content access"]]', 1, 0),
  ('carvan-e-hind', 'Carvan-e-Hind', 'The community platform for Carvan-e-Hind Trust — events, media, and members.', 'Flutter developer & maintainer', '2024 — 2026', '["iOS","Android"]', 'Social Networking', '/media/apps/carvan-e-hind/icon.webp', '["/media/apps/carvan-e-hind/shot1.webp","/media/apps/carvan-e-hind/shot2.webp"]', 5, 4, '["Flutter","REST APIs","Firebase","Push notifications"]', '{"ios":"https://apps.apple.com/in/app/carvan-e-hind/id6745079091"}', 'A community app for the Dawoodi Bohra community: announcements, events, media, and member engagement in one place, built and maintained end to end in Flutter.', '["Event discovery and community announcements","Media library with offline-friendly downloads","Member directory and engagement flows","Push notifications for time-sensitive updates","Android and iOS releases from a single codebase"]', 'Community apps live or die on trust: the content has to be current, the notifications have to be relevant, and the app has to work on the phones people actually carry. I rebuilt the delivery around a predictable release train, moved content operations to a structured pipeline, and kept the UI simple enough for first-time smartphone users. The result is a 5-star rated app that the trust actually uses.', '[["5.0★","App Store rating"],["2","Platforms"],["Single","Flutter codebase"]]', 1, 1),
  ('lumio-tv', 'Lumio TV', 'An IPTV player that behaves well on phones, tablets, and Android TV.', 'Lead developer', '2024', '["iOS","Android","Web","Android TV"]', 'Entertainment', '/media/apps/lumio-tv/icon.webp', '["/media/apps/lumio-tv/shot1.webp","/media/apps/lumio-tv/shot2.webp"]', NULL, NULL, '["Flutter","M3U","Xtream Codes","EPG","Android TV"]', '{"ios":"https://apps.apple.com/us/app/lumio-tv-iptv-player/id6766064122","android":"https://play.google.com/store/apps/details?id=app.lumio_iptv.com","web":"https://lumiotv.web.app/"}', 'A multi-provider IPTV client with M3U and Xtream support, live EPG, channel management, and resilient playback across mobile, web, and Android TV.', '["M3U playlists and Xtream Codes providers","Live EPG guide with channel metadata","Favorites, recents, and channel search","Android TV focus navigation and remote support","Resilient stream recovery and error states","Shared Flutter core across iOS, Android, and web"]', 'IPTV is a hostile environment: providers change formats, streams stall, and users expect television-grade reliability. I built Lumio TV around a tolerant parser, explicit playback states, and a remote-first TV interface, then reused the same core for mobile and web. The interesting engineering was not the player — it was making failure legible so users know whether the network, the provider, or the stream is the problem.', '[["4","Platforms"],["M3U + Xtream","Provider formats"],["TV-first","Interaction model"]]', 1, 2),
  ('14-stars', '14 Stars', 'An all-in-one Islamic app for Quran, Hadith, Nauhas, and daily practice.', 'Flutter developer (contributed)', '2023', '["iOS"]', 'Education', '/media/apps/14-stars/icon.webp', '["/media/apps/14-stars/shot1.webp","/media/apps/14-stars/shot2.webp"]', 4.8, 12, '["Flutter","Audio playback","Calendar","Offline content"]', '{"ios":"https://apps.apple.com/ae/app/14-stars/id1526359119"}', 'A comprehensive Islamic companion covering Quran, Hadith, Nauhas, Manqabats, Ziyarats, a calendar, Namaz timings, and Qibla direction.', '["Quran, Hadith, Nauhas, and Manqabats","Ziyarats and religious calendar","Namaz timings and Qibla direction","Audio playback and offline reading","Long-term maintenance across iOS releases"]', '14 Stars is a mature codebase with a large content surface and years of accumulated behavior. My contribution focused on stabilizing playback, improving content navigation, and keeping releases healthy across iOS versions. Working on a widely used app with an established audience is a different discipline from greenfield work: every change has to respect habits people already have.', '[["4.8★","App Store rating"],["iOS","Platform"],["Long-term","Maintenance"]]', 1, 3),
  ('nutrabay', 'Nutrabay', 'Mobile commerce for one of India’s largest nutrition retailers.', 'Contributing mobile engineer', '2023', '["iOS","Android","Web"]', 'Health & Fitness', '/media/apps/nutrabay/icon.webp', '["/media/apps/nutrabay/shot1.webp","/media/apps/nutrabay/shot2.webp"]', NULL, NULL, '["Flutter","E-commerce","REST APIs","Analytics"]', '{"ios":"https://apps.apple.com/ae/app/nutrabay-shop-supplements/id1583551779","android":"https://play.google.com/store/apps/details?id=com.nutrabay"}', 'A high-traffic nutrition e-commerce app covering catalogue browsing, offers, checkout, and order tracking across mobile and web.', '["Catalogue and category browsing at scale","Cart, checkout, and payment flows","Offers and promotional surfaces","Order tracking and account management","Analytics-driven merchandising surfaces"]', 'E-commerce engineering is judged on conversion and crash-free sessions. On Nutrabay I worked on the mobile experience around product discovery and checkout, where small latency and layout decisions have direct revenue consequences. The lesson that stayed with me: in commerce, performance work is product work.', '[["3","Platforms"],["E-commerce","Domain"],["Checkout","Critical path"]]', 1, 4),
  ('pool-inspection', 'Pool Inspection', 'Field-service inspections for pool compliance and safety audits.', 'Mobile developer', '2019 — 2020', '["iOS"]', 'Business', '/media/apps/pool-inspection/icon.webp', '["/media/apps/pool-inspection/shot1.webp","/media/apps/pool-inspection/shot2.webp"]', NULL, NULL, '["Flutter","Offline forms","Camera","PDF reports"]', '{"ios":"https://apps.apple.com/ae/app/pool-inspection-apps/id1528932146"}', 'A field-service app for inspectors: structured checklists, photo evidence, and compliance reports generated on site, often without reliable connectivity.', '["Offline-first inspection forms","Photo capture and evidence attachment","Compliance checklists and scoring","Generated PDF reports","Sync when connectivity returns"]', 'Inspectors work poolside, not in an office. That constraint shaped everything: forms must survive app restarts, photos must queue for upload, and the report has to be produced before leaving the property. Building offline-first workflows taught me more about state management than any tutorial — every edge case is a real user standing in the sun waiting for a screen to load.', '[["Offline","First-class"],["On-site","PDF reports"],["iOS","Platform"]]', 1, 5),
  ('petassy', 'Petassy', 'Pet care in one app — appointments, a social feed, places, and reminders.', 'Creator · Flutter developer', '2023', '["iOS","Android"]', 'Lifestyle', '/media/apps/petassy/icon.webp', '[]', NULL, NULL, '["Flutter","Dart","GetX","Firebase Auth","Cloud Firestore","Firebase Storage","FCM","Google Maps"]', '{}', 'A Flutter pet-care platform with three in-app roles — pet parent, veterinarian, and nutritionist: pet profiles, appointment scheduling, a social feed called Expaw, real-time chat, nearby places on the map, and care reminders on Firebase.', '["Pet profiles with registration and editing","Role-based flows for pet parents, vets, and nutritionists","Expaw social feed with photo and video posts, likes, and comments","Appointment scheduling with local notification reminders","Real-time messaging between pet parents and professionals","Nearby places, saved locations, and Google Maps integration","Shopping section, profile, and settings"]', 'Petassy started from a simple observation: pet care is scattered across chats, notes, and phone calls. I built it as a Flutter app around three roles that share one data model — pet parents, vets, and nutritionists — with Firebase Auth, Firestore, Storage, and Cloud Messaging behind it. The work that mattered was not the screens but keeping the same pet record coherent across a social feed, appointments, chat, and reminders, including Google Maps places and permission-gated flows. It is the project where I learned how much of product engineering is roles, permissions, and making the same entity legible in different contexts.', '[["3","In-app roles"],["Real-time","Chat & feed"],["Firebase","Auth, storage, push"]]', 1, 6),
  ('blankspace', 'BlankSpace', 'A fill-in-the-blank party word game — think alike, score big.', 'Creator · Flutter developer', NULL, '["iOS","Android"]', 'Word game', '/media/apps/blankspace/icon.webp', '[]', NULL, NULL, '["Flutter","Dart","Riverpod","go_router","Supabase Realtime","Firebase Remote Config","RevenueCat","AdMob"]', '{}', 'A party word game built on a pure-Dart round engine: solo, pass-and-play, and online rooms, with bots, scoring, a local leaderboard, and an optional premium tier.', '["Solo, pass-and-play, and online rooms joined by room code","Round engine that deals cue cards, locks answers, and scores matching answers","Bot opponents and a local leaderboard","Rewarded-ad peek and a RevenueCat premium paywall","Word filtering before answers are scored","Firebase Remote Config for tuning without a release"]', 'BlankSpace is built as a pure-Dart game engine wrapped by a Flutter interface: the engine deals the round cue, tracks the writing phase, locks each seat, and scores the matches, so solo, pass-and-play, and online games run the same rules. Online rooms use Supabase with one realtime channel per room code, while monetisation is a RevenueCat paywall and a rewarded-ad peek. The interesting problem was keeping turn order and scoring identical whether the other seats are bots in the same room or people on another phone.', '[["3","Play modes"],["Pure Dart","Round engine"],["Realtime","Online rooms"]]', 1, 7),
  ('bulbvpn', 'BULB VPN', 'A V2Ray VPN client with subscription import, QR scanning, and live connection stats.', 'Creator · Flutter developer', NULL, '["iOS","Android"]', 'Utilities', '/media/apps/bulbvpn/icon.webp', '[]', NULL, NULL, '["Flutter","Dart","Riverpod","go_router","flutter_vless","Firebase Remote Config","Analytics","Crashlytics","mobile_scanner"]', '{"github":"https://github.com/hasanabbassorathiya/BULBVPN"}', 'A Flutter VPN client for iOS and Android: import subscriptions, configs, or QR codes, pick a server, and watch live connection state and traffic statistics.', '["VMess, VLESS, Trojan, and Shadowsocks configuration support through flutter_vless","Import by subscription URL, pasted config, clipboard, or QR scan","Server list with search, protocol filters, and favourites","Live connection state with download, upload, and duration statistics","Firebase Remote Config, Analytics, and Crashlytics wired in","English, Spanish, and Portuguese localisation"]', 'BULB VPN keeps the plugin at arm’s length: flutter_vless sits behind a VpnEngine abstraction, so connection state, statistics, and failures are modelled by the app instead of leaking plugin types into the UI. Users add servers by subscription URL, raw config, clipboard paste, or QR scan, and the app normalises them into one server model with search, protocol filters, and favourites. That structure made it possible to add live connection stats, remote-config defaults, and crash reporting without rewriting the connection flow.', '[["4","Protocols"],["4","Import paths"],["2","Platforms"]]', 1, 8),
  ('hoda', 'Hoda', 'A bilingual pilgrimage companion, in French and English.', 'Publisher', NULL, '["iOS","Android"]', 'Books', '/media/apps/hoda/icon.webp', '["/media/apps/hoda/shot1.webp","/media/apps/hoda/shot2.webp"]', NULL, NULL, '[]', '{"ios":"https://apps.apple.com/ae/app/id6755375239","android":"https://play.google.com/store/apps/details?id=app.hoda.com"}', 'A French/English pilgrimage guide covering sacred sites, their history, Hajj and Umrah rituals, supplications with transliteration and translation, and the spiritual meaning of the Ziyarat of Arbaeen.', '["Practical pilgrimage guidance in French and English","Pilgrimage sites in Iran, Iraq, Syria, Lebanon, Egypt, and Saudi Arabia","Historical context and explanations of Hajj and Umrah rituals","Supplications with transliteration and translation","Spiritual guidance on the Ziyarat of Arbaeen"]', NULL, '[]', 1, 9),
  ('fragrance-of-mastership', 'Fragrance of Mastership', 'Dr. Shabeeb Rizvi’s collection of traditions, available as a book app.', 'Publisher', NULL, '["iOS"]', 'Books', '/media/apps/fragrance-of-mastership/icon.webp', '["/media/apps/fragrance-of-mastership/shot1.webp","/media/apps/fragrance-of-mastership/shot2.webp"]', NULL, NULL, '[]', '{"ios":"https://apps.apple.com/ae/app/id6480333197"}', 'Fragrance of Mastership by Dr. Shabeeb Rizvi collects traditions on wilayat (mastership), Imam Ali and the eleven Imams, alongside traditions about Lady Fatima Zahra.', '["A collection of traditions on wilayat (mastership)","Traditions concerning Imam Ali and the eleven Imams","Traditions concerning Lady Fatima Zahra"]', NULL, '[]', 1, 10),
  ('wallmaster', 'WallMaster', 'Discover wallpapers and short videos for your phone.', 'Store listing', NULL, '["Android"]', 'Photography', '/media/apps/wallmaster/icon.webp', '["/media/apps/wallmaster/shot1.webp","/media/apps/wallmaster/shot2.webp"]', NULL, NULL, '[]', '{"android":"https://play.google.com/store/apps/details?id=com.hasanabbassorathiya.wallmaster"}', 'An Android wallpaper and video app with search, popular tags, downloads, and sharing. Its Google Play description identifies Pexels as the source of its photo and video content.', '["Wallpaper discovery through search and popular tags","Short videos to browse, play, and download","Home-screen and lock-screen wallpaper selection","Share favorite images with friends and family"]', NULL, '[]', 1, 11),
  ('business-mind', 'Business Mind: Money Empire', 'An idle business simulation about building and growing an empire.', 'Store listing', NULL, '["Android"]', 'Simulation', '/media/apps/business-mind/icon.webp', '["/media/apps/business-mind/shot1.webp","/media/apps/business-mind/shot2.webp"]', NULL, NULL, '[]', '{"android":"https://play.google.com/store/apps/details?id=game.businessmind.hasanabbas"}', 'An idle business tycoon game with businesses to run, employees and upgrades, simulated stock and crypto investments, real estate, and progress while away from the app.', '["Tap-to-earn businesses, employees, and upgrades","Simulated stock market, crypto, and real-estate investing","Offline earnings, daily challenges, and login streaks","Legacy prestige progression and cloud saves"]', NULL, '[]', 1, 12),
  ('klix', 'KLIX', 'A GCC shopping app for unique products, delivered within 24 hours.', 'Senior mobile engineer · Masaar', '2022', '["iOS","Android"]', 'Shopping', '/media/apps/klix/icon.webp', '["/media/apps/klix/shot1.webp","/media/apps/klix/shot2.webp"]', 4.4, 5, '["Flutter","Dart","E-commerce","Authentication"]', '{"ios":"https://apps.apple.com/hr/app/klix-%D9%83%D9%84%D9%8A%D9%83%D8%B3/id1593578496","android":"https://play.google.com/store/apps/details?id=com.iklix.klix"}', 'A cross-border storefront for shoppers across the GCC: unique products sourced from around the world, cash-on-delivery or card payment, and delivery inside 24 hours.', '["Unique products sourced from around the world","Cash on delivery or credit card at checkout","Delivery across GCC markets within 24 hours","Browsing, cart, and checkout in one app","iOS and Android releases from a single codebase"]', 'Klix is the cross-border e-commerce app Masaar ran for GCC shoppers, importing products from Japan and Korea. I joined as senior mobile engineer and re-architected the Flutter application for scalability and maintainability, rebuilt secure authentication, and reworked the purchase journey; the UX and workflow changes contributed to roughly 25% better conversion. Cross-border retail lives or dies on trust at checkout and on the delivery promise, so that is where the rebuild concentrated.', '[["+25%","Conversion after UX rework"],["2","Platforms"],["24h","Delivery promise"]]', 1, 13),
  ('urban-ledger', 'Urban Ledger', 'Track. Remind. Collect. Split. — the digital ledger for UAE businesses.', 'Team lead · Vervali Systems', '2021', '["iOS","Android"]', 'Business', '/media/apps/urban-ledger/icon.webp', '["/media/apps/urban-ledger/shot1.webp","/media/apps/urban-ledger/shot2.webp"]', 5, 5, '["Flutter","Dart","Payments","Fintech"]', '{"ios":"https://apps.apple.com/ae/app/urban-ledger/id1617320844","android":"https://play.google.com/store/apps/details?id=com.ul.urbanledger&hl=en"}', 'A digital ledger and collections app for UAE businesses: payment links, QR codes, tap-to-pay, staff contactless cards, VAT invoices, payment reminders, and Zolt split payments.', '["Payment links, QR codes, and tap-to-pay collection","Digital ledger (khata) with SMS, WhatsApp, and email reminders","VAT invoices carrying a payment link and QR code","Staff contactless cards for field teams","Zolt split payments on UAE credit cards"]', 'Urban Ledger began as a digital ledger for UAE shopkeepers and grew into a collections platform: payment links, QR codes, tap-to-pay, and staff cards, all reconciled in one ledger. I led the Flutter build at Vervali Systems — payment flows, secure API communication, and validation logic — and mentored the team on architecture and code review. The product question was trust: a merchant has to believe the number on the screen matches the money in the bank, so every flow was designed around a record the user can check.', '[["5.0★","App Store rating"],["2","Platforms"],["UAE","Market"]]', 1, 14)
